#ifndef CODE_OFFSETS_H
#define CODE_OFFSETS_H

#if defined(__x86_64__)
#define PADDING_008_BYTES   "mov (0), %rax\n"
#elif defined(__aarch64__)
#define PADDING_004_BYTES                     "mov x0, #0\n"
#define PADDING_008_BYTES   PADDING_004_BYTES "ldr x0, [x0]\n"
#elif defined(__thumb__)
#define PADDING_002_BYTES                     "mov r0, #0\n\t"
#define PADDING_004_BYTES   PADDING_002_BYTES "ldr r0, [r0]\n\t"
#define PADDING_008_BYTES   PADDING_004_BYTES PADDING_004_BYTES
#endif
#define PADDING_016_BYTES   PADDING_008_BYTES PADDING_008_BYTES
#define PADDING_032_BYTES   PADDING_016_BYTES PADDING_016_BYTES
#define PADDING_064_BYTES   PADDING_032_BYTES PADDING_032_BYTES
#define PADDING_128_BYTES   PADDING_064_BYTES PADDING_064_BYTES

#endif //CODE_OFFSETS_H
